from ._core import *  # noqa: F401,F403  (helpers, constants, op decorator)


@op("actors_in_level")
def actors_in_level(args):
    limit = int(args.get("limit", 1000))
    actors = _actor_sub().get_all_level_actors()
    world = unreal.EditorLevelLibrary.get_editor_world() if hasattr(unreal, "EditorLevelLibrary") else None
    recs = [_actor_record(a) for a in actors[:limit]]
    return _envelope("actors_in_level", True, {
        "level": world.get_path_name() if world else None,
        "count": len(actors), "actors": recs, "truncated": len(actors) > limit,
    })


_THEME_MAT_DIR = "/Game/GameForge/Materials/Theme"
_THEME_MAT_CACHE = {}


def _theme_color_material(color):
    """Return (creating once) a MaterialInstanceConstant of BasicShapeMaterial tinted with ``color``."""
    try:
        rgba = [max(0.0, min(1.0, float(c))) for c in list(color)[:4]]
        rgba += [1.0] * (4 - len(rgba))
        key = "".join("%02X" % int(round(c * 255)) for c in rgba[:3])
        if key in _THEME_MAT_CACHE:
            return _THEME_MAT_CACHE[key]
        path = "%s/MI_GF_Tint_%s" % (_THEME_MAT_DIR, key)
        if unreal.EditorAssetLibrary.does_asset_exist(path):
            mi = unreal.EditorAssetLibrary.load_asset(path)
        else:
            parent = unreal.EditorAssetLibrary.load_asset(
                "/Engine/BasicShapes/BasicShapeMaterial.BasicShapeMaterial")
            if parent is None:
                return None
            mi = unreal.AssetToolsHelpers.get_asset_tools().create_asset(
                "MI_GF_Tint_%s" % key, _THEME_MAT_DIR, unreal.MaterialInstanceConstant,
                unreal.MaterialInstanceConstantFactoryNew())
            if mi is None:
                return None
            mel = unreal.MaterialEditingLibrary
            mel.set_material_instance_parent(mi, parent)
            mel.set_material_instance_vector_parameter_value(mi, "Color", unreal.LinearColor(*rgba))
            mel.update_material_instance(mi)
            unreal.EditorAssetLibrary.save_loaded_asset(mi)
        _THEME_MAT_CACHE[key] = mi
        return mi
    except Exception:
        return None


def _snap_actor_to_ground(actor, offset, ignore_prefixes=("GF_Decor",)):
    """Line-trace straight down (ignoring the actor and decoration) and move it onto the first blocking hit."""
    try:
        world = unreal.EditorLevelLibrary.get_editor_world()
        loc = actor.get_actor_location()
        ignore = [actor]
        prefixes = tuple(p for p in (ignore_prefixes or ()) if p)
        if prefixes:
            for other in _actor_sub().get_all_level_actors():
                try:
                    if other is not actor and other.get_actor_label().startswith(prefixes):
                        ignore.append(other)
                except Exception:
                    continue
        start = unreal.Vector(loc.x, loc.y, loc.z + 20000.0)
        end = unreal.Vector(loc.x, loc.y, loc.z - 40000.0)
        hit = unreal.SystemLibrary.line_trace_single(
            world, start, end, unreal.TraceTypeQuery.TRACE_TYPE_QUERY1, False, ignore,
            unreal.DrawDebugTrace.NONE, True)
        if hit is None:
            return False
        tup = hit.to_tuple() if hasattr(hit, "to_tuple") else None
        blocking = bool(tup[0]) if tup else bool(getattr(hit, "blocking_hit", False))
        if not blocking:
            return False
        impact = tup[5] if tup else hit.impact_point  # (blocking, initial_overlap, time, distance, location, impact_point, ...)
        actor.set_actor_location(unreal.Vector(loc.x, loc.y, impact.z + offset), False, False)
        return True
    except Exception:
        return False


@op("spawn_actor", mutates=True, reversibility="transactional")
def spawn_actor(args):
    cls = _load_class(args.get("actor_class", "StaticMeshActor"))
    if cls is None:
        return _envelope("spawn_actor", False, errors=["actor class not found: %s" % args.get("actor_class")])
    label = args.get("label")
    with unreal.ScopedEditorTransaction("GameForge spawn_actor"):
        actor = _actor_sub().spawn_actor_from_class(cls, _vec(args.get("location")), _rot(args.get("rotation")))
        if actor is None:
            return _envelope("spawn_actor", False, errors=["spawn_actor_from_class returned None"])
        if label:
            actor.set_actor_label(label)
        if "location" in args:
            actor.set_actor_location(_vec(args["location"]), False, False)
        if "rotation" in args:
            actor.set_actor_rotation(_rot(args["rotation"]), False)
        mesh_path = args.get("static_mesh")
        if not mesh_path and isinstance(actor, unreal.StaticMeshActor):
            mesh_path = "/Engine/BasicShapes/Cube.Cube"
        if mesh_path and isinstance(actor, unreal.StaticMeshActor):
            mesh = unreal.EditorAssetLibrary.load_asset(mesh_path)
            if mesh:
                actor.static_mesh_component.set_editor_property("static_mesh", mesh)
        scale = args.get("scale")
        if scale:
            actor.set_actor_scale3d(_vec(scale, (1, 1, 1)))
        mobility = args.get("mobility")
        if mobility and actor.root_component:
            actor.root_component.set_mobility(getattr(unreal.ComponentMobility, mobility.upper()))
        if "light_intensity" in args and hasattr(actor, "light_component") and actor.light_component:
            actor.light_component.set_intensity(float(args["light_intensity"]))
        warnings_pre = []
        material = args.get("material")
        mat = unreal.EditorAssetLibrary.load_asset(material) if material else None
        if material and mat is None:
            warnings_pre.append("material not found, using theme colour/basic material: %s" % material)
        color = args.get("color")
        if isinstance(actor, unreal.StaticMeshActor):
            if color and (mat is None or not material):
                mat = _theme_color_material(color) or mat
            if mat is None:
                mat = unreal.EditorAssetLibrary.load_asset(
                    "/Engine/BasicShapes/BasicShapeMaterial.BasicShapeMaterial")
            if mat:
                actor.static_mesh_component.set_material(0, mat)
        light_color = args.get("light_color")
        if light_color and hasattr(actor, "light_component") and actor.light_component:
            try:
                lc = list(light_color) + [1.0] * (4 - len(light_color))
                actor.light_component.set_light_color(unreal.LinearColor(*lc[:4]), True)
            except Exception as exc:  # light colour is cosmetic; never fail the spawn for it
                warnings_pre.append("light colour skipped: %s" % exc)
        if args.get("snap_to_ground"):
            snapped = _snap_actor_to_ground(actor, float(args.get("ground_offset", 0.0)),
                                            args.get("snap_ignore_prefixes", ["GF_Decor"]))
            if not snapped:
                warnings_pre.append("snap_to_ground: no surface found below actor; kept requested height")
    # Direct readback from the spawned actor instance
    rec = _actor_record(actor)
    warnings = list(warnings_pre)
    if "location" in args and not args.get("snap_to_ground"):
        req = args["location"]
        act_loc = rec.get("location", {})
        dx = abs(act_loc.get("x", 0.0) - float(req.get("x", 0.0)))
        dy = abs(act_loc.get("y", 0.0) - float(req.get("y", 0.0)))
        dz = abs(act_loc.get("z", 0.0) - float(req.get("z", 0.0)))
        if dx > 10.0 or dy > 10.0 or dz > 10.0:
            warnings.append(
                f"spawn_actor location discrepancy: requested ({req.get('x')}, {req.get('y')}, {req.get('z')}) "
                f"vs confirmed ({act_loc.get('x'):.1f}, {act_loc.get('y'):.1f}, {act_loc.get('z'):.1f})"
            )
    return _envelope("spawn_actor", True, rec, warnings=warnings, reversibility="transactional")


@op("delete_actor", mutates=True, reversibility="transactional")
def delete_actor(args):
    actor = _find_actor(args["label"])
    if actor is None:
        return _envelope("delete_actor", False, errors=["actor not found: %s" % args["label"]])
    with unreal.ScopedEditorTransaction("GameForge delete_actor"):
        _actor_sub().destroy_actor(actor)
    gone = _find_actor(args["label"]) is None
    return _envelope("delete_actor", gone, {"label": args["label"], "deleted": gone},
                     errors=[] if gone else ["read-back: actor still present"], reversibility="transactional")


@op("set_actor_property", mutates=True, reversibility="transactional")
def set_actor_property(args):
    actor = _find_actor(args["label"])
    if actor is None:
        return _envelope("set_actor_property", False, errors=["actor not found: %s" % args["label"]])
    name, value = args["property"], args["value"]
    if args.get("asset"):
        # Object reference properties (e.g. a NiagaraSystem) take the loaded asset, not its path string.
        value = unreal.EditorAssetLibrary.load_asset(value)
        if value is None:
            return _envelope("set_actor_property", False, errors=["asset not found: %s" % args["value"]])
    elif isinstance(value, list):
        if name.lower() == "tags":
            value = [unreal.Name(v) if isinstance(v, str) else v for v in value]
        else:
            value = [_vec(v) if isinstance(v, dict) and set(v) == {"x", "y", "z"} else v for v in value]
    elif isinstance(value, dict) and set(value) == {"x", "y", "z"}:
        value = _vec(value)
    elif isinstance(value, dict) and {"r", "g", "b"} <= set(value) <= {"r", "g", "b", "a"}:
        # Colour properties (PickupColor, BodyColor) used to be passed as raw dicts and silently skipped.
        value = unreal.LinearColor(float(value["r"]), float(value["g"]), float(value["b"]), float(value.get("a", 1.0)))
    try:
        with unreal.ScopedEditorTransaction("GameForge set_actor_property"):
            actor.set_editor_property(name, value)
        actual = actor.get_editor_property(name)
        return _envelope("set_actor_property", True, {"label": args["label"], "property": name, "value": str(actual)},
                         reversibility="transactional")
    except Exception as exc:
        return _envelope("set_actor_property", True, {"label": args["label"], "property": name, "skipped": str(exc)},
                         warnings=[f"Property '{name}' skipped on {args['label']}: {exc}"], reversibility="transactional")


@op("actor_set_tags", mutates=True, reversibility="transactional")
def actor_set_tags(args):
    actor = _find_actor(args["label"])
    if actor is None:
        return _envelope("actor_set_tags", False, errors=["actor not found: %s" % args["label"]])
    tags = [unreal.Name(t) if isinstance(t, str) else t for t in args.get("tags", [])]
    with unreal.ScopedEditorTransaction("GameForge actor_set_tags"):
        actor.set_editor_property("tags", tags)
    readback = [str(t) for t in actor.get_editor_property("tags")]
    return _envelope("actor_set_tags", True, {"label": args["label"], "tags": readback},
                     reversibility="transactional")



@op("scene_set_manual_exposure", mutates=True, reversibility="transactional")
def scene_set_manual_exposure(args):
    """Unbound PostProcessVolume with manual exposure, so captures do not depend on eye adaptation."""
    label = args.get("label", "GF_Exposure")
    with unreal.ScopedEditorTransaction("GameForge scene_set_manual_exposure"):
        vol = _find_actor(label)
        if vol is None:
            vol = _actor_sub().spawn_actor_from_class(unreal.PostProcessVolume, unreal.Vector(0, 0, 0))
            vol.set_actor_label(label)
        vol.set_editor_property("unbound", True)
        st = vol.get_editor_property("settings")
        st.set_editor_property("override_auto_exposure_method", True)
        st.set_editor_property("auto_exposure_method", unreal.AutoExposureMethod.AEM_MANUAL)
        st.set_editor_property("override_auto_exposure_bias", True)
        st.set_editor_property("auto_exposure_bias", float(args.get("exposure_bias", 10.0)))
        vol.set_editor_property("settings", st)
    rec = _exposure_record(vol)
    ok = rec["method"] == "AEM_MANUAL" and rec["unbound"]
    return _envelope("scene_set_manual_exposure", ok, rec, reversibility="transactional",
                     errors=[] if ok else ["read-back does not show manual exposure"])


@op("scene_get_exposure", reversibility="read-only")
def scene_get_exposure(args):
    vol = _find_actor(args.get("label", "GF_Exposure"))
    if not isinstance(vol, unreal.PostProcessVolume):
        return _envelope("scene_get_exposure", False, errors=["no PostProcessVolume with that label"])
    return _envelope("scene_get_exposure", True, _exposure_record(vol))


@op("new_level", mutates=True, reversibility="snapshot-only")
def new_level(args):
    path = args["level_path"]
    if_exists = args.get("if_exists", "load")
    if unreal.EditorAssetLibrary.does_asset_exist(path):
        if if_exists == "replace":
            try:
                world = unreal.EditorLevelLibrary.get_editor_world() if hasattr(unreal, "EditorLevelLibrary") else None
                curr_path = world.get_path_name() if world else ""
                if curr_path and (path in curr_path or curr_path.startswith(path)):
                    if hasattr(unreal, "EditorLoadingAndSavingUtils"):
                        unreal.EditorLoadingAndSavingUtils.new_blank_map(False)
                    elif hasattr(_level_sub(), "new_level"):
                        _level_sub().new_level("/Engine/Maps/Templates/Template_Default")
            except Exception:
                pass
            unreal.EditorAssetLibrary.delete_asset(path)
        elif if_exists != "load":
            return _envelope("new_level", False, {"level_path": path, "exists": True},
                             errors=["level already exists: " + path])
        else:
            ok = _level_sub().load_level(path)
            return _envelope("new_level", bool(ok), {"level_path": path, "exists": True, "loaded_existing": True},
                             warnings=["level existed; loaded instead of created"], affected=[path],
                             reversibility="snapshot-only", errors=[] if ok else ["load_level failed"])
    partitioned = bool(args.get("partitioned", False))
    ok = _level_sub().new_level(path, partitioned) if partitioned else _level_sub().new_level(path)
    if ok:
        try:
            _level_sub().save_current_level()
        except Exception:
            pass
    exists = unreal.EditorAssetLibrary.does_asset_exist(path)
    is_partitioned = _world_is_partitioned()
    if partitioned and not is_partitioned:
        ok = False
    return _envelope("new_level", bool(ok) and exists, {"level_path": path, "exists": exists, "partitioned": is_partitioned},
                     affected=[path], reversibility="snapshot-only",
                     errors=[] if (ok and exists) else ["new_level failed or level not on disk"])


@op("load_level", mutates=False)
def load_level(args):
    path = args["level_path"]
    if not unreal.EditorAssetLibrary.does_asset_exist(path):
        ok = _level_sub().new_level(path)
        if ok:
            try:
                _level_sub().save_current_level()
            except Exception:
                pass
        return _envelope("load_level", bool(ok), {"level_path": path, "auto_created": True},
                         warnings=["level did not exist on disk; created before loading"])
    ok = _level_sub().load_level(path)
    return _envelope("load_level", bool(ok), {"level_path": args["level_path"]})


